def main():
    assert not OUT.exists();OUT.mkdir(parents=True)
    seeds=[]
    old=json.loads((ROOT/'test_queries.frozen.json').read_text(encoding='utf-8'))+json.loads((ROOT/'dev_queries.json').read_text(encoding='utf-8'))+json.loads((ROOT.parents[2]/'ml_search/evaluation_queries.json').read_text(encoding='utf-8'))
    train=[json.loads(l) for l in (ROOT/'training/train.jsonl').read_text(encoding='utf-8').splitlines()]
    prior=[r['query'] for r in old]+[r['query'] for r in train]
    for n,line in enumerate(SEEDS.splitlines(),1):
        cat,*qs=line.split('|');assert len(qs)==3
        seeds.append({'family_id':f'NEW-F{n:02}','category':cat,'queries':qs})
    assert len(seeds)==50
    # Stratified family allocation, then deterministic shuffle. 17 dev / 33 test families.
    wanted={'mood':4,'atmosphere':3,'colloquial':3,'negation':3,'plot':2,'specialized':2}
    rng=random.Random(2026091502);dev_ids=set()
    for cat,count in wanted.items():
        rows=[r for r in seeds if r['category']==cat];rng.shuffle(rows);dev_ids.update(r['family_id'] for r in rows[:count])
    sets={'dev':[],'test':[]};overlap=[]
    for family in seeds:
        split='dev' if family['family_id'] in dev_ids else 'test'
        for n,q in enumerate(family['queries'],1):
            similarity,nearest=max((SequenceMatcher(None,q.casefold(),p.casefold()).ratio(),p) for p in prior)
            overlap.append({'query_id':f"{family['family_id']}-V{n}",'nearest_prior_query':nearest,'character_similarity':similarity,'manual_semantic_overlap_review_required':True})
            assert q.casefold() not in {p.casefold() for p in prior}
            sets[split].append({'query_id':f"{family['family_id']}-V{n}",'family_id':family['family_id'],'category':family['category'],'query':q,
                'source':'agent_authored_synthetic_query_first','judgments':None,'expected_empty':None,'annotation_status':'pending','model_evaluation_performed':False})
    for split,rows in sets.items():(OUT/f'{split}_queries.draft.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
    (OUT/'overlap-screening.json').write_text(json.dumps(overlap,ensure_ascii=False,indent=2),encoding='utf-8')
    policy={'status':'query_draft_frozen_not_a_ready_independent_test','dev_queries':len(sets['dev']),'test_queries':len(sets['test']),
        'dev_families':17,'test_families':33,'families_disjoint':True,'exact_prior_query_duplicates':0,
        'semantic_family_overlap_audit_pending':True,'real_user_queries':0,'qrels_pending':True,
        'test_book_holdout_selection_pending':True,'new_training_must_wait_for_holdout_book_and_related_work_reservation':True,
        'all_existing_heldout_books_remain_reserved':True,'no_model_queries_run':True,
        'freeze_draft_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.glob('*.draft.json')},
        'test_usage':'Do not retrieve or inspect test model results while selecting integration settings. After family audit and independent annotation, freeze qrels and use once.'}
    (OUT/'split-policy.json').write_text(json.dumps(policy,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(policy))
if __name__=='__main__':main()
